root='F:\AER_RETRA_CASE'; addpath(genpath(root)); day=fullfile(root,'CCN_FULL_RERUN_20260821','day_20220601'); ds=dir(fullfile(day,'orbit_*','CALIPSO_results_2022_06_01_hdf.mat')); A=load(fullfile(ds(3).folder,ds(3).name),'T_all'); T=A.T_all; good=isfinite(T.Ext)&T.Ext>0&isfinite(T.Back)&T.Back>0&isfinite(T.Depol)&T.Depol>0.05&T.Depol<0.31&isfinite(T.RH)&T.RH>0&T.RH<100&isfinite(T.Type)&T.Type>=1&T.Type<=7; T=T(good,:); P0=load(which('Parameter_Particle_CALISPO.mat')); P=P0.data; E0=load(which('Extinction_Normalized.mat')); E=E0.Extinction_N; [Nd,~]=Calc_Nd_OMCAM(T,P,struct('Extinction_N',E)); [mx,ix]=max(Nd); fid=fopen(fullfile(day,'outlier_formula.txt'),'w'); fprintf(fid,'maxNd=%g row=%d Ext=%g Back=%g Depol=%g RH=%g Type=%d Height=%g\n',mx,ix,T.Ext(ix),T.Back(ix),T.Depol(ix),T.RH(ix),T.Type(ix),T.Height(ix)); fprintf(fid,'P fields: %s\n',strjoin(fieldnames(P),',')); fprintf(fid,'fine_v=%g coarse_v=%g fine_rm=%g coarse_rm=%g fine_gsd=%g coarse_gsd=%g\n',P.v_i_fine(T.Type(ix)),P.v_i_coarse(T.Type(ix)),P.r_mean_fine(T.Type(ix)),P.r_mean_coarse(T.Type(ix)),P.GSD_fine(T.Type(ix)),P.GSD_coarse(T.Type(ix))); rhidx=min(100,max(1,round(T.RH(ix)))); fprintf(fid,'RHindex=%d ExtNorm type2=%g type3=%g\n',rhidx,E(2,rhidx),E(3,rhidx)); fclose(fid);
